"use strict";class tCookie{constructor(t="/",e=365){this.path=t,this.expires="",this.setExpires(e)}setExpires(t){const e=new Date;e.setTime(e.getTime()+24*t*60*60*1e3),this.expires="expires="+e.toUTCString()}set(t,e){document.cookie=t+"="+JSON.stringify(e)+";"+this.expires+";path="+this.path}get(t){t+="=";let e=document.cookie.split(";");for(let s=0;s<e.length;s++){let i=e[s];for(;" "==i.charAt(0);)i=i.substring(1);if(0==i.indexOf(t))return JSON.parse(i.substring(t.length,i.length))}return!1}}